mkdir -p /app/output /app/output/assets && cat > /app/output/assets/styles.css << 'EOF'
:root {
  --navy: #0A1628;
  --navy-2: #10223d;
  --gold: #c5a25d;
  --teal: #1f7a7a;
  --white: #ffffff;
  --gray-50: #f7f8fa;
  --gray-100: #eef1f5;
  --gray-200: #dde2ea;
  --gray-500: #5f6b7a;
  --gray-700: #2e3a4d;
  --container: 1200px;
  --shadow: 0 10px 30px rgba(10, 22, 40, 0.12);
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: 'Inter', 'Segoe UI', Roboto, Arial, sans-serif;
  color: var(--gray-700);
  background: var(--white);
  line-height: 1.6;
}
h1,h2,h3,h4 {
  margin: 0 0 12px;
  color: var(--navy);
  line-height: 1.2;
}
h1,h2 { font-family: 'Merriweather', Georgia, serif; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(var(--container), 92vw); margin: 0 auto; }
.btn {
  display: inline-block;
  padding: 12px 22px;
  border-radius: 3px;
  font-weight: 600;
  font-size: 0.95rem;
  border: 1px solid transparent;
}
.btn-primary { background: var(--gold); color: var(--navy); }
.btn-outline { border-color: var(--white); color: var(--white); }
.btn-navy { background: var(--navy); color: var(--white); }
.top-announcement {
  background: var(--navy);
  color: var(--white);
  font-size: .9rem;
  padding: 10px 0;
}
.top-announcement a { color: var(--gold); font-weight: 600; }
.site-header {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(255,255,255,.98);
  border-bottom: 1px solid var(--gray-100);
}
.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-height: 74px;
}
.brand { font-size: 1.5rem; font-weight: 800; color: var(--navy); letter-spacing: .3px; }
.nav-links {
  display: flex;
  align-items: center;
  gap: 24px;
}
.nav-link { font-weight: 600; color: var(--navy); padding: 26px 0; }
.has-mega { position: relative; }
.mega-menu {
  position: absolute;
  left: 0;
  top: 100%;
  width: min(980px, 90vw);
  background: var(--white);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow);
  padding: 28px;
  display: none;
}
.mega-menu.open { display: grid; grid-template-columns: 2fr 1fr; gap: 28px; }
.mega-col h4 { font-size: .95rem; text-transform: uppercase; letter-spacing: .06em; color: var(--gray-500); }
.mega-list { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 18px; margin: 10px 0 0; padding: 0; list-style: none; }
.mega-list a { color: var(--navy); font-weight: 600; font-size: .95rem; }
.mobile-toggle { display: none; background: none; border: 0; font-size: 1.5rem; color: var(--navy); }
.mobile-nav {
  display: none;
  border-top: 1px solid var(--gray-100);
  padding: 14px 0 20px;
}
.mobile-acc button {
  width: 100%;
  text-align: left;
  padding: 12px 0;
  background: none;
  border: 0;
  border-bottom: 1px solid var(--gray-100);
  color: var(--navy);
  font-weight: 700;
}
.mobile-panel { display: none; padding: 8px 0 12px 12px; }
.mobile-panel.open { display: block; }
.hero {
  min-height: 72vh;
  color: var(--white);
  display: flex;
  align-items: center;
  background-size: cover;
  background-position: center;
  position: relative;
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, rgba(10,22,40,.82), rgba(10,22,40,.35));
}
.hero .container { position: relative; z-index: 1; }
.hero h1 { color: var(--white); font-size: clamp(2rem, 4vw, 3.4rem); max-width: 760px; }
.hero p { max-width: 620px; font-size: 1.05rem; }
.section { padding: 72px 0; }
.section.alt { background: var(--gray-50); }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; }
.cards-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; }
.cards-4 { display: grid; grid-template-columns: repeat(4,1fr); gap: 20px; }
.cards-6 { display: grid; grid-template-columns: repeat(3,1fr); gap: 22px; }
.card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  padding: 24px;
  box-shadow: 0 4px 15px rgba(10,22,40,.05);
}
.tag { display:inline-block; font-size:.75rem; color:var(--teal); text-transform:uppercase; font-weight:700; letter-spacing:.06em; margin-bottom:8px; }
.what-tabs { display: grid; grid-template-columns: 260px 1fr; gap: 30px; }
.tab-nav { border-left: 2px solid var(--gray-200); }
.tab-nav button {
  width: 100%;
  text-align: left;
  background: none;
  border: 0;
  padding: 16px 18px;
  font-weight: 700;
  color: var(--navy);
}
.tab-nav button.active { border-left: 3px solid var(--gold); background: var(--gray-50); }
.tab-panel { display: none; }
.tab-panel.active { display: block; }
.newsletter {
  background: linear-gradient(90deg, var(--navy), var(--navy-2));
  color: var(--white);
  padding: 42px;
  border-radius: 8px;
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
}
.newsletter p, .newsletter h3 { color: var(--white); }
.site-footer { background: var(--navy); color: #d4dbe6; padding: 48px 0 24px; }
.footer-grid { display:grid; grid-template-columns: 2fr 1fr 1fr; gap: 24px; }
@media (max-width: 980px) {
  .nav-links { display: none; }
  .mobile-toggle { display: inline-block; }
  .mobile-nav.open { display: block; }
  .grid-2,.cards-3,.cards-4,.cards-6,.what-tabs,.footer-grid { grid-template-columns: 1fr; }
  .hero { min-height: 60vh; }
}
EOF

cat > /app/output/assets/main.js << 'EOF'
const megaTrigger = document.querySelector('[data-mega-trigger]');
const megaMenu = document.querySelector('[data-mega-menu]');
if (megaTrigger && megaMenu) {
  let closeTimeout;
  const open = () => { clearTimeout(closeTimeout); megaMenu.classList.add('open'); };
  const close = () => { closeTimeout = setTimeout(() => megaMenu.classList.remove('open'), 100); };
  megaTrigger.addEventListener('mouseenter', open);
  megaTrigger.addEventListener('mouseleave', close);
  megaTrigger.addEventListener('click', (e) => {
    e.preventDefault();
    megaMenu.classList.toggle('open');
  });
  megaMenu.addEventListener('mouseenter', open);
  megaMenu.addEventListener('mouseleave', close);
}

const mobileBtn = document.querySelector('[data-mobile-toggle]');
const mobileNav = document.querySelector('[data-mobile-nav]');
if (mobileBtn && mobileNav) {
  mobileBtn.addEventListener('click', () => mobileNav.classList.toggle('open'));
}
document.querySelectorAll('.mobile-acc button').forEach((btn) => {
  btn.addEventListener('click', () => {
    const panel = btn.nextElementSibling;
    panel.classList.toggle('open');
  });
});

document.querySelectorAll('[data-tab]').forEach((btn) => {
  btn.addEventListener('click', () => {
    const target = btn.getAttribute('data-tab');
    document.querySelectorAll('[data-tab]').forEach((b) => b.classList.remove('active'));
    document.querySelectorAll('.tab-panel').forEach((p) => p.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById(target)?.classList.add('active');
  });
});

const slides = document.querySelectorAll('.partner-slide');
let slideIndex = 0;
const showSlide = (i) => slides.forEach((s, idx) => s.style.display = idx === i ? 'block' : 'none');
if (slides.length) {
  showSlide(slideIndex);
  document.querySelector('[data-slide-next]')?.addEventListener('click', () => {
    slideIndex = (slideIndex + 1) % slides.length;
    showSlide(slideIndex);
  });
  document.querySelector('[data-slide-prev]')?.addEventListener('click', () => {
    slideIndex = (slideIndex - 1 + slides.length) % slides.length;
    showSlide(slideIndex);
  });
}
EOF

